cmd:
P="${TUIQA_HOME}/proj"; n() { find "$P" -name 'untitled*' | wc -l | tr -d ' '; }; (
 while [ "$(n)" -lt 1 ]; do sleep 0.05; done; echo "package agent" > "$P/agent.go";
 while [ "$(n)" -lt 2 ]; do sleep 0.05; done; mv "$P/agent.go" "$P/renamed.go";
 while [ "$(n)" -lt 3 ]; do sleep 0.05; done; rm "$P/renamed.go"; mkdir "$P/madedir"
) & exec "${LAZYFINDER_BIN}" --sidebar "$P"
